INSERT INTO data_documents (data_key,source_path,sha256,payload) VALUES ('ai.accessories','ai-service/data/accessories.json','8f80d26b1383970a8ca087d71471da2fd85ad0d040882c25fabc91c742b93c9f',CAST('[{"id":"non_la","name":"Nón lá","slot":"head","genders":["nu","nam"],"byGender":true,"usesAccent":true},{"id":"non_quai_thao","name":"Nón quai thao","slot":"head","genders":["nu"],"usesAccent":true},{"id":"khan_van","name":"Khăn vấn","slot":"hair","genders":["nu","nam"],"byGender":true,"usesAccent":true},{"id":"khan_mo_qua","name":"Khăn mỏ quạ","slot":"hair","genders":["nu"],"usesAccent":false},{"id":"khan_xep","name":"Khăn xếp","slot":"hair","genders":["nam"],"usesAccent":true},{"id":"hoa_cai_toc","name":"Hoa cài tóc","slot":"hair","genders":["nu"],"usesAccent":true},{"id":"guoc","name":"Guốc","slot":"feet","genders":["nu","nam"],"byGender":true,"usesAccent":false},{"id":"hai_theu","name":"Hài thêu","slot":"feet","genders":["nu","nam"],"byGender":true,"usesAccent":true},{"id":"giay_bup_be","name":"Giày búp bê","slot":"feet","genders":["nu"],"usesAccent":true},{"id":"giay_ta","name":"Giày ta (vải đen)","slot":"feet","genders":["nam"],"usesAccent":false},{"id":"sneaker","name":"Sneaker","slot":"feet","genders":["nu","nam"],"byGender":true,"usesAccent":false},{"id":"tui","name":"Túi cói","slot":"hand","genders":["nu","nam"],"byGender":true,"usesAccent":true},{"id":"quat_giay","name":"Quạt giấy","slot":"hand","genders":["nu","nam"],"byGender":true,"usesAccent":true},{"id":"kieng_bac","name":"Kiềng bạc","slot":"neck","genders":["nu"],"usesAccent":false},{"id":"trang_suc","name":"Bông tai + vòng tay","slot":"jewelry","genders":["nu"],"usesAccent":false}]' AS JSONB));
INSERT INTO data_documents (data_key,source_path,sha256,payload) VALUES ('ai.checklist','ai-service/data/checklist.json','ef0763ee7657e2df04e14465850076e4f43de5326ab5a0b5e50990286b8aa962',CAST('{"_ghi_chu":"Gợi ý món tương đương ngoài đời cho checklist ''soi và mặc theo'' (trang Tuỳ chỉnh / Nhận xét). Chỉ mô tả cách tìm đồ, không thêm thông tin lịch sử.","garments":{"ao_dai":"Áo dài tay dài, cổ đứng, xẻ tà hai bên (truyền thống hoặc cách tân đều được)","ao_ngu_than":"Áo ngũ thân cổ đứng, thân suông rộng, cài khuy chéo bên phải","ao_tu_than":"Áo tứ thân mở vạt trước, mặc kèm yếm và thắt lưng buộc trước bụng","nhat_binh":"Áo nhật bình cổ vuông có dải cổ bản rộng, tay rộng (thường đi thuê tại tiệm cổ phục)","ao_ba_ba":"Áo bà ba cổ tròn, xẻ hai bên hông, tay dài (vải lụa hoặc cotton mềm)"},"bottoms":{"quan":"Quần ống suông dài tới mắt cá (quần lụa, quần âu ống rộng màu trơn đều được)","vay":"Váy dài qua bắp chân, màu trơn (chân váy đụp, chân váy maxi suông)"},"accessories":{"non_la":"Nón lá có quai vải buộc dưới cằm","non_quai_thao":"Nón quai thao (thường đi thuê cùng bộ tứ thân)","khan_van":"Khăn vấn quấn quanh đầu (có loại vấn sẵn, chỉ việc đội)","khan_mo_qua":"Khăn mỏ quạ màu đen, gấp nhọn trên trán","khan_xep":"Khăn xếp đội sẵn (mua hoặc thuê kèm áo dài, ngũ thân nam)","hoa_cai_toc":"Kẹp hoặc trâm hoa cài một bên tóc","guoc":"Guốc gỗ quai ngang","hai_theu":"Hài vải thêu mũi cong","giay_bup_be":"Giày búp bê mũi tròn, đế bệt","giay_ta":"Giày vải đen đế bệt","sneaker":"Sneaker trắng trơn, càng ít hoạ tiết càng hợp","tui":"Túi cói hoặc túi đan xách tay cỡ nhỏ","quat_giay":"Quạt giấy gấp","kieng_bac":"Kiềng bạc đeo cổ","trang_suc":"Bông tai nhỏ và vòng tay đơn giản"},"lining":"Viền cổ, viền tay hoặc yếm","accent":"Màu khăn, quai nón, thắt lưng, túi"}' AS JSONB));
INSERT INTO data_documents (data_key,source_path,sha256,payload) VALUES ('ai.culture-cards','ai-service/data/culture-cards.json','b12b11faf2fd4a84885d3956d134651a036cbec1d5b1dba0a9a5860d1227e708',CAST('[{"id":"CC_AO_DAI","garmentId":"ao_dai","title":"Áo dài","body":"Áo dài hiện đại phát triển từ áo ngũ thân và được cách tân trong thế kỷ 20 với dáng ôm, xẻ tà cao hai bên. Ngày nay áo dài xuất hiện trong lễ Tết, cưới hỏi, trường học và các sự kiện trang trọng.","sources":[],"verified":false},{"id":"CC_NGU_THAN","garmentId":"ao_ngu_than","title":"Áo ngũ thân","body":"Áo ngũ thân may từ năm thân vải: bốn thân chính tượng trưng cho tứ thân phụ mẫu và một thân con phía trong. Áo có cổ đứng, cài khuy chéo sang một bên, phổ biến dưới thời Nguyễn và đang được nhiều bạn trẻ phục dựng.","sources":[],"verified":false},{"id":"CC_TU_THAN","garmentId":"ao_tu_than","title":"Áo tứ thân","body":"Áo tứ thân gồm bốn vạt, hai vạt trước thường buộc lại, mặc cùng yếm, váy và thắt lưng. Trang phục gắn với hình ảnh người phụ nữ vùng Kinh Bắc và đồng bằng Bắc Bộ.","sources":[],"verified":false},{"id":"CC_NHAT_BINH","garmentId":"nhat_binh","title":"Áo nhật bình","body":"Áo nhật bình là lễ phục của nữ giới trong cung đình triều Nguyễn, nổi bật với phần cổ áo bản rộng phủ qua vai. Vì vốn là lễ phục, áo hợp với lễ hội, sự kiện văn hóa hơn là mặc dạo phố thường ngày.","sources":[],"verified":false},{"id":"CC_BA_BA","garmentId":"ao_ba_ba","title":"Áo bà ba","body":"Áo bà ba là áo ngắn, xẻ hai bên hông, thường mặc cùng quần ống rộng. Trang phục gắn với đời sống thường ngày của người dân Nam Bộ.","sources":[],"verified":false}]' AS JSONB));
INSERT INTO data_documents (data_key,source_path,sha256,payload) VALUES ('ai.fallback-comments','ai-service/data/fallback-comments.json','6d2fd105f2620df0f0c6fa2fd8b4a81ab935e6c04368edae61890b6923f85e47',CAST('{"byGarmentOccasion":{"ao_ngu_than|ky_yeu":{"title":"Ngũ thân cho ngày kỷ yếu","comment":"Áo ngũ thân giúp cả lớp trông chỉn chu mà vẫn trẻ trung trong ảnh tập thể. Màu {color1} làm chủ đạo, {color2} làm điểm nhấn sẽ lên ảnh rất sáng."},"ao_dai|ky_yeu":{"title":"Áo dài kỷ yếu nhẹ nhàng","comment":"Áo dài là lựa chọn quen thuộc mà không bao giờ cũ cho ngày chia tay mái trường. Tông {color1} phối {color2} giữ cho ảnh dịu và sáng."},"ao_tu_than|le_hoi_chua":{"title":"Tứ thân đi hội","comment":"Áo tứ thân hợp không khí lễ hội và hội làng. Màu {color1} trầm ấm, thêm {color2} cho điểm nhấn là vừa đẹp."}},"byGarment":{"ao_dai":{"title":"Áo dài thanh lịch","comment":"Áo dài dễ mặc, hợp nhiều dịp. Màu {color1} kết hợp {color2} cho tổng thể hài hòa."},"ao_ngu_than":{"title":"Ngũ thân chỉn chu","comment":"Áo ngũ thân có cổ đứng và 5 khuy, nhìn trang trọng mà vẫn trẻ. Màu {color1} phối {color2} khá ăn ý."},"ao_tu_than":{"title":"Tứ thân dân dã","comment":"Áo tứ thân mang nét mộc mạc, rất hợp chụp ảnh. Màu {color1} với {color2} giữ được chất truyền thống."}},"byRule":{"R07":"Đi sneaker vẫn ổn nha, chỉ cần giữ cổ đứng và đủ 5 khuy để áo vẫn ra chất ngũ thân.","R12":"Toàn trắng kèm khăn trắng dễ khiến người lớn liên tưởng tới tang phục, bạn thử thêm một màu ấm nhé.","R15":"Nhật bình vốn là lễ phục cung đình, dạo phố thì áo dài hoặc ngũ thân sẽ tự nhiên hơn."},"defaultTip":"Bạn có thể vào studio để đổi màu và phụ kiện theo ý mình."}' AS JSONB));
INSERT INTO data_documents (data_key,source_path,sha256,payload) VALUES ('ai.garments','ai-service/data/garments.json','cf2f13e044d2e941d87c115c551388f8b9fae5de8575c735139d4ce758b1cf3b',CAST('[{"id":"ao_dai","name":"Áo dài","genders":["nu","nam"],"hasSvg":true,"occasions":["tet","ky_yeu","dam_cuoi","le_hoi_chua","dao_pho"],"defaultColors":{"main":"trang_nga","bottom":"trang_nga"},"cultureCardId":"CC_AO_DAI"},{"id":"ao_ngu_than","name":"Áo ngũ thân","genders":["nu","nam"],"hasSvg":true,"occasions":["tet","ky_yeu","dam_cuoi","le_hoi_chua","dao_pho"],"defaultColors":{"main":"do_son","bottom":"den_tuyen"},"cultureCardId":"CC_NGU_THAN"},{"id":"ao_tu_than","name":"Áo tứ thân","genders":["nu"],"hasSvg":true,"occasions":["tet","ky_yeu","le_hoi_chua","dao_pho"],"defaultColors":{"main":"nau_dat","lining":"do_son","bottom":"den_tuyen","accent":"xanh_ngoc"},"cultureCardId":"CC_TU_THAN"},{"id":"nhat_binh","name":"Áo nhật bình","genders":["nu"],"hasSvg":true,"occasions":["tet","dam_cuoi","le_hoi_chua"],"defaultColors":{"main":"vang_hoang","lining":"do_son","bottom":"trang_nga"},"cultureCardId":"CC_NHAT_BINH"},{"id":"ao_ba_ba","name":"Áo bà ba","genders":["nu","nam"],"hasSvg":true,"occasions":["tet","le_hoi_chua","dao_pho"],"defaultColors":{"main":"be_kem","bottom":"den_tuyen"},"cultureCardId":"CC_BA_BA"}]' AS JSONB));
INSERT INTO data_documents (data_key,source_path,sha256,payload) VALUES ('ai.occasions','ai-service/data/occasions.json','51a844bd70d09732830529bc74a94178cf05138cd76cd10db25993af5e26a163',CAST('[{"id":"tet","name":"Tết / du xuân","palette":["do_son","vang_hoang","hong_dao","xanh_ngoc","trang_nga"],"defaultAccessories":{"ao_dai":["khan_van","tui","giay_bup_be"],"ao_ngu_than":["khan_xep","khan_van","hai_theu"],"ao_tu_than":["khan_mo_qua","non_quai_thao","kieng_bac"],"nhat_binh":["khan_van","guoc"],"ao_ba_ba":["non_la"]}},{"id":"ky_yeu","name":"Chụp kỷ yếu / tốt nghiệp","palette":["hong_dao","trang_nga","xanh_lam","vang_hoang","xanh_ngoc"],"defaultAccessories":{"ao_dai":["non_la","giay_bup_be"],"ao_ngu_than":["khan_xep","khan_van","sneaker"],"ao_tu_than":["non_quai_thao"],"ao_ba_ba":["non_la","sneaker"]}},{"id":"dam_cuoi","name":"Đám cưới (khách / bê tráp)","palette":["do_son","hong_dao","vang_hoang","xanh_lam"],"defaultAccessories":{"ao_dai":["trang_suc","tui","hai_theu"],"ao_ngu_than":["khan_xep","khan_van","hai_theu"],"ao_tu_than":["khan_mo_qua","kieng_bac"],"nhat_binh":["khan_van","trang_suc","hai_theu"]}},{"id":"le_hoi_chua","name":"Lễ hội / đi chùa","palette":["nau_dat","be_kem","xanh_reu","vang_hoang","trang_nga"],"defaultAccessories":{"ao_dai":["guoc"],"ao_ngu_than":["khan_xep","khan_van","giay_ta"],"ao_tu_than":["non_quai_thao","khan_mo_qua","kieng_bac"],"nhat_binh":["khan_van"],"ao_ba_ba":["non_la"]}},{"id":"dao_pho","name":"Dạo phố / chụp ảnh","palette":["xanh_ngoc","hong_dao","be_kem","den_tuyen","xanh_lam"],"defaultAccessories":{"ao_dai":["non_la","quat_giay","giay_bup_be"],"ao_ngu_than":["sneaker","tui"],"ao_tu_than":["non_la"],"ao_ba_ba":["non_la","tui","hoa_cai_toc"]}}]' AS JSONB));
