cục","genders":["nam"],"garments":["ao_dai","ao_ngu_than","ao_ba_ba"],"note":"Cành tùng ngang ngực, cây tùng trên đá ở tà"},{"id":"song_nuoc","name":"Sóng nước (hải thuỷ)","kind":"placement","group":"Vẽ / thêu theo bố cục","genders":["nam","nu"],"garments":["ao_dai","ao_ngu_than"],"note":"Sọc lập thuỷ, sóng và núi ở gấu như áo triều phục, mặt trời ở ngực"},{"id":"cuc","name":"Hoa cúc","kind":"placement","group":"Vẽ / thêu theo bố cục","genders":["nu"],"garments":["ao_dai","ao_ngu_than","ao_ba_ba"],"note":"Ba bông cúc vươn từ lá ở gấu, bông nhỏ ở vai"},{"id":"mai_vang","name":"Mai vàng","kind":"placement","group":"Vẽ / thêu theo bố cục","genders":["nu","nam"],"garments":["ao_dai","ao_ngu_than","ao_ba_ba"],"note":"Cành mai vàng ngày Tết từ gấu lên hông, nhành nhỏ ở vai"},{"id":"chim_lac","name":"Chim Lạc","kind":"placement","group":"Vẽ / thêu theo bố cục","genders":["nam","nu"],"garments":["ao_dai","ao_ngu_than","ao_ba_ba"],"note":"Đàn chim Lạc Đông Sơn bay chéo, dải vòng tròn ở cổ và gấu"},{"id":"buom","name":"Bướm và hoa","kind":"placement","group":"Vẽ / thêu theo bố cục","genders":["nu"],"garments":["ao_dai","ao_ngu_than","ao_ba_ba"],"note":"Bướm bay lên từ cụm hoa nhỏ ở gấu, hai cánh bướm ở vai"},{"id":"tho_may","name":"Gấm chữ Thọ & mây","kind":"tile","group":"Vải in đều","tile":80,"motif":"<circle cx=''18'' cy=''18'' r=''9.5'' fill=''none'' stroke=''#E4DDB4'' stroke-opacity=''0.5'' stroke-width=''1.5''/><path d=''M12 13 H24 M12 18 H24 M12 23 H24 M18 13 V23 M14 10 V13 M22 10 V13 M14 23 V26 M22 23 V26'' fill=''none'' stroke=''#E4DDB4'' stroke-opacity=''0.5'' stroke-width=''1.2''/><circle cx=''58'' cy=''58'' r=''9.5'' fill=''none'' stroke=''#E4DDB4'' stroke-opacity=''0.5'' stroke-width=''1.5''/><path d=''M52 53 H64 M52 58 H64 M52 63 H64 M58 53 V63 M54 50 V53 M62 50 V53 M54 63 V66 M62 63 V66'' fill=''none'' stroke=''#E4DDB4'' stroke-opacity=''0.5'' stroke-width=''1.2''/><path d=''M28 52 c4 -6 11 -6 13 0 c2 5 -4 7 -6 2 M39 55 c6 3 12 9 22 6 M70 22 c-4 -6 -11 -6 -13 0 c-2 5 4 7 6 2 M59 25 c-6 3 -12 9 -22 6 M4 40 c6 -3 10 2 16 -2 M60 74 c4 -4 10 -2 14 -6'' fill=''none'' stroke=''#E4DDB4'' stroke-opacity=''0.32'' stroke-width=''1.1'' stroke-linecap=''round''/>","note":"Vải gấm in chìm: chữ Thọ tròn xen vân mây, cùng tông nền"},{"id":"hoa_van_tron","name":"Hoa văn tròn","kind":"tile","group":"Vải in đều","tile":34,"motif":"<circle cx=''17'' cy=''17'' r=''6.5'' fill=''#D9B44A'' fill-opacity=''0.8''/><circle cx=''17'' cy=''17'' r=''3'' fill=''none'' stroke=''#8A6A1E'' stroke-opacity=''0.6'' stroke-width=''0.8''/>"},{"id":"hoa_dao","name":"Hoa đào nhỏ","kind":"tile","group":"Vải in đều","tile":30,"motif":"<g fill=''#F6B8C4'' fill-opacity=''0.9''><circle cx=''15'' cy=''11'' r=''3''/><circle cx=''19'' cy=''14'' r=''3''/><circle cx=''17.5'' cy=''19'' r=''3''/><circle cx=''12.5'' cy=''19'' r=''3''/><circle cx=''11'' cy=''14'' r=''3''/></g><circle cx=''15'' cy=''15.5'' r=''1.6'' fill=''#D9B44A''/>"},{"id":"ke_soc","name":"Kẻ sọc","kind":"tile","group":"Vải in đều","tile":12,"motif":"<rect x=''0'' y=''0'' width=''4'' height=''12'' fill=''#000'' fill-opacity=''0.16''/>"},{"id":"cham_bi","name":"Chấm bi","kind":"tile","group":"Vải in đều","tile":16,"motif":"<circle cx=''8'' cy=''8'' r=''2.4'' fill=''#FFFFFF'' fill-opacity=''0.75''/>"}]' AS JSONB));
INSERT INTO data_documents (data_key,source_path,sha256,payload) VALUES ('ai.quiz','ai-service/data/quiz.json','7460072ef891b611ad16439280fafcd1a00c0b9616a711db4de5a87f9bb8f9e5',CAST('[{"id":"occasion","field":"occasion","type":"single","required":true,"question":"Bạn sẽ mặc Việt phục vào dịp nào?","options":[{"value":"tet","label":"Tết / du xuân"},{"value":"ky_yeu","label":"Chụp kỷ yếu / tốt nghiệp"},{"value":"dam_cuoi","label":"Đám cưới, ăn hỏi"},{"value":"le_hoi_chua","label":"Lễ hội / đi chùa"},{"value":"dao_pho","label":"Dạo phố / chụp ảnh"}],"placeholder":"Hoặc kể dịp của bạn, ví dụ: đi hội làng cuối tuần"},{"id":"weather","field":"weather","type":"single","required":false,"question":"Thời tiết hôm đó thế nào?","options":[{"value":"nang_nong","label":"Nắng nóng"},{"value":"mat_me","label":"Mát mẻ"},{"value":"lanh","label":"Se lạnh / lạnh"},{"value":"mua","label":"Có mưa"}],"placeholder":"Ví dụ: tháng 12 ở Hà Nội, trời hanh"},{"id":"setting","field":"setting","type":"single","required":false,"question":"Bạn ở trong nhà hay ngoài trời?","options":[{"value":"ngoai_troi","label":"Ngoài trời"},{"value":"trong_nha","label":"Trong nhà"},{"value":"ca_hai","label":"Cả hai"}],"placeholder":"Ví dụ: chụp ở công viên rồi vào nhà hàng"},{"id":"timeOfDay","field":"timeOfDay","type":"single","required":false,"question":"Vào buổi nào?","options":[{"value":"ban_ngay","label":"Ban ngày"},{"value":"buoi_toi","label":"Buổi tối"}],"placeholder":"Ví dụ: tiệc tối"},{"id":"role","field":"role","type":"single","required":false,"question":"Bạn tham gia với vai trò gì?","options":[{"value":"khach","label":"Khách mời"},{"value":"nhan_vat_chinh","label":"Nhân vật chính (cô dâu, chú rể, người tốt nghiệp…)"},{"value":"be_trap","label":"Bê tráp / phụ dâu, phụ rể"},{"value":"nhom","label":"Đi cùng nhóm / cả lớp"},{"value":"chup_anh","label":"Đi chơi, chụp ảnh"}],"placeholder":"Ví dụ: mình là phù dâu"},{"id":"style","field":"style","type":"single","required":false,"question":"Bạn thích phong cách nào?","options":[{"value":"truyen_thong","label":"Truyền thống"},{"value":"toi_gian","label":"Tối giản"},{"value":"duong_pho","label":"Đường phố, cá tính"},{"value":"pastel","label":"Pastel, nhẹ nhàng"}],"placeholder":"Ví dụ: nhẹ nhàng nhưng vẫn nổi bật"},{"id":"gender","field":"gender","type":"single","required":false,"question":"Người mặc là nam hay nữ?","options":[{"value":"nu","label":"Nữ"},{"value":"nam","label":"Nam"}],"placeholder":""},{"id":"colors","field":"preferredColors","type":"multi","required":false,"question":"Màu bạn thích? (chọn tối đa 3, có thể bỏ qua)","options":"palette","placeholder":"Ví dụ: thích tông ấm, không thích màu hồng"}]' AS JSONB));
INSERT INTO data_documents (data_key,source_path,sha256,payload) VALUES ('ai.rules','ai-service/data/rules.json','e45549b791d1f91c66ecedd7b561e06f46f5b12b9fb0029cd55a706a060e4da0',CAST('[{"id":"R01","level":"ok","criterion":"cau_truc","when":{"all":[{"garment":["ao_tu_than"]},{"hasAccessory":"non_quai_thao"}]},"reason":"Bộ trang phục gắn với vùng Kinh Bắc","suggestion":{"text":"Đội thêm khăn mỏ quạ bên dưới nón, đeo kiềng bạc để trọn bộ quan họ"},"sources":["SRC01"],"verified":false},{"id":"R07","level":"consider","criterion":"cach_tan","when":{"all":[{"garment":["ao_ngu_than"]},{"hasAccessory":"sneaker"}]},"reason":"Cách tân chấp nhận được, nên giữ cổ đứng và 5 khuy","suggestion":{"text":"Chọn sneaker trắng trơn, giữ cổ đứng và đủ 5 khuy"},"sources":["SRC02"],"verified":false},{"id":"R12","level":"risk","criterion":"boi_canh","when":{"all":[{"occasion":["dam_cuoi","tet"]},{"allColorsIn":["trang_nga","trang_tinh"]},{"hasAccessory":"khan_van"}]},"reason":"Toàn màu trắng kèm khăn trắng gợi liên tưởng tang phục","suggestion":{"text":"Đổi màu chính sang đỏ son hoặc hồng đào","patch":{"colors":{"main":"do_son","bottom":"trang_nga"}}},"sources":["SRC03"],"verified":false},{"id":"R15","level":"consider","criterion":"boi_canh","when":{"all":[{"garment":["nhat_binh"]},{"occasion":["dao_pho"]}]},"reason":"Vốn là lễ phục cung đình triều Nguyễn","suggestion":{"text":"Dạo phố nên chọn áo dài hoặc áo ngũ thân"},"sources":["SRC04"],"verified":false},{"id":"R20","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["mua"]},{"hasAccessory":"guoc"}]},"reason":"Trời mưa, guốc gỗ dễ trơn trượt và thấm nước","suggestion":{"text":"Đi giày kín mũi hoặc dép có đế bám thay cho guốc gỗ"},"sources":[],"verified":false},{"id":"R21","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["nang_nong"]},{"setting":["ngoai_troi","ca_hai"]},{"garment":["nhat_binh","ao_tu_than","ao_ngu_than"]}]},"reason":"Áo nhiều lớp, mặc lâu ngoài trời nắng nóng dễ bí và ra mồ hôi","suggestion":{"text":"Chọn áo dài hoặc áo bà ba vải mỏng, hoặc hẹn chụp lúc sáng sớm, chiều muộn"},"sources":[],"verified":false},{"id":"R22","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["nang_nong"]},{"setting":["ngoai_troi","ca_hai"]},{"mainColorIn":["den_tuyen","xanh_lam","nau_dat","tim_hue"]}]},"reason":"Màu tối hấp nắng, mặc ngoài trời lúc nắng nóng sẽ nóng hơn","suggestion":{"text":"Đổi màu chính sang màu sáng như trắng ngà hoặc be kem","patch":{"colors":{"main":"be_kem"}}},"sources":[],"verified":false},{"id":"R23","level":"ok","criterion":"boi_canh","when":{"all":[{"weather":["lanh"]},{"garment":["ao_ngu_than","nhat_binh","ao_tu_than"]}]},"reason":"Áo nhiều lớp, may dày, hợp với tiết trời se lạnh","suggestion":{"text":"Có thể mặc thêm áo lót giữ nhiệt bên trong"},"sources":[],"verified":false},{"id":"R24","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["mua"]},{"mainColorIn":["trang_nga","trang_tinh"]}]},"reason":"Áo màu trắng gặp mưa dễ ướt, lộ và bám bẩn","suggestion":{"text":"Chọn màu đậm hơn như hồng đào hoặc xanh lam","patch":{"colors":{"main":"hong_dao"}}},"sources":[],"verified":false},{"id":"R25","level":"consider","criterion":"boi_canh","when":{"all":[{"role":["khach"]},{"occasion":["dam_cuoi"]},{"garment":["nhat_binh"]}]},"reason":"Nhật bình là lễ phục rất trang trọng, khách dự cưới mặc dễ nổi bật hơn cô dâu","suggestion":{"text":"Khách nên chọn áo dài hoặc áo ngũ thân"},"sources":[],"verified":false},{"id":"R26","level":"consider","criterion":"boi_canh","when":{"all":[{"role":["khach"]},{"occasion":["dam_cuoi"]},{"mainColorIn":["do_son"]}]},"reason":"Màu đỏ thường dành cho cô dâu, khách mặc đỏ dễ trùng với nhân vật chính","suggestion":{"text":"Đổi sang hồng đào hoặc xanh lam","patch":{"colors":{"main":"hong_dao"}}},"sources":[],"verified":false},{"id":"R27","level":"ok","criterion":"boi_canh","when":{"all":[{"role":["nhan_vat_chinh"]},{"occasion":["dam_cuoi"]},{"mainColorIn":["do_son","vang_hoang"]}]},"reason":"Đỏ và vàng là sắc màu quen thuộc của lễ cưới truyền thống","suggestion":{"text":"Có thể thêm khăn vấn cùng tông để trọn bộ"},"sources":[],"verified":false},{"id":"R28","level":"consider","criterion":"cach_tan","when":{"all":[{"occasion":["dam_cuoi","le_hoi_chua"]},{"pattern":["cham_bi","ke_soc"]},{"style":["truyen_thong"]}]},"reason":"Hoạ tiết chấm bi, kẻ sọc mang nét hiện đại, khác tinh thần truyền thống bạn chọn","suggestion":{"text":"Đổi sang vải trơn hoặc hoa văn tròn","patch":{"pattern":"hoa_van_tron"}},"sources":[],"verified":false},{"id":"R30","level":"ok","criterion":"cau_truc","when":{"all":[{"gender":["nam"]},{"garment":["ao_ngu_than","ao_dai"]},{"hasAccessory":"khan_xep"}]},"reason":"Khăn xếp đi cùng áo dài, áo ngũ thân là bộ lễ phục quen thuộc của nam giới","suggestion":{"text":"Chọn khăn cùng tông màu sẫm (đen, xanh lam) để tổng thể trang nhã"},"sources":["SRC05"],"verified":false},{"id":"R31","level":"consider","criterion":"phu_kien","when":{"all":[{"garment":["nhat_binh"]},{"any":[{"hasAccessory":"sneaker"},{"hasAccessory":"giay_bup_be"}]}]},"reason":"Nhật bình là lễ phục, giày hiện đại làm giảm vẻ trang trọng","suggestion":{"text":"Đổi sang hài thêu hoặc guốc gỗ"},"sources":["SRC04"],"verified":false},{"id":"R32","level":"ok","criterion":"phu_kien","when":{"all":[{"hasAccessory":"hai_theu"},{"any":[{"garment":["nhat_binh","ao_ngu_than"]},{"occasion":["dam_cuoi"]}]}]},"reason":"Hài thêu hợp với lễ phục và không khí lễ cưới","suggestion":{"text":"Chọn màu hài trùng màu điểm nhấn của khăn để đồng bộ"},"sources":[],"verified":false},{"id":"R33","level":"consider","criterion":"phu_kien","when":{"all":[{"hasAccessory":"non_quai_thao"},{"garment":["ao_dai","ao_ba_ba"]}]},"reason":"Nón quai thao gắn với áo tứ thân của liền chị quan họ, đi với áo dài hay bà ba dễ lệch tinh thần","suggestion":{"text":"Đổi sang nón lá, hoặc đổi áo sang áo tứ thân"},"sources":["SRC01"],"verified":false},{"id":"R34","level":"ok","criterion":"phu_kien","when":{"all":[{"garment":["ao_tu_than"]},{"any":[{"hasAccessory":"khan_mo_qua"},{"hasAccessory":"kieng_bac"}]}]},"reason":"Khăn mỏ quạ, kiềng bạc là phụ kiện quen thuộc đi cùng áo tứ thân","suggestion":{"text":"Đi lễ hội có thể thêm nón quai thao; chụp ảnh trong nhà thì khăn mỏ quạ là đủ"},"sources":["SRC01"],"verified":false},{"id":"R35","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["mua"]},{"hasAccessory":"quat_giay"}]},"reason":"Quạt giấy gặp mưa dễ ướt, rách","suggestion":{"text":"Thay bằng túi cói hoặc để quạt cho buổi chụp trong nhà"},"sources":[],"verified":false},{"id":"R36","level":"consider","criterion":"boi_canh","when":{"all":[{"role":["khach"]},{"occasion":["dam_cuoi"]},{"pattern":["phuong_hoang"]}]},"reason":"Phượng hoàng thường là hoạ tiết áo cưới của cô dâu, khách mặc dễ trùng nhân vật chính","suggestion":{"text":"Khách dự cưới nên chọn cành đào, sen hoặc hạc và mai","patch":{"pattern":"canh_dao"}},"sources":[],"verified":false},{"id":"R37","level":"ok","criterion":"dac_trung","when":{"all":[{"pattern":["sen","hoi_van","hac_mai"]},{"occasion":["le_hoi_chua","tet"]}]},"reason":"Sen, hồi văn, hạc và mai là hoạ tiết truyền thống, hợp không khí lễ hội, ngày Tết","suggestion":{"text":"Giữ nền trơn một màu để hoạ tiết nổi bật"},"sources":[],"verified":false},{"id":"R38","level":"ok","criterion":"dac_trung","when":{"all":[{"gender":["nam"]},{"pattern":["tung","truc","rong_may","song_nuoc"]}]},"reason":"Tùng, trúc, rồng, sóng nước là hoạ tiết quen thuộc trên áo nam, gợi khí chất vững vàng","suggestion":{"text":"Chọn nền xanh lam hoặc nâu đất để hoạ tiết vàng nổi bật"},"sources":[],"verified":false},{"id":"R39","level":"ok","criterion":"dac_trung","when":{"all":[{"pattern":["mai_vang","canh_dao"]},{"occasion":["tet"]}]},"reason":"Mai vàng, hoa đào là hoa ngày Tết, hợp không khí du xuân","suggestion":{"text":"Kết hợp khăn vấn hoặc khăn xếp cùng tông với hoa"},"sources":[],"verified":false}]' AS JSONB));
INSERT INTO data_documents (data_key,source_path,sha256,payload) VALUES ('ai.scoring','ai-service/data/scoring.json','e4f4121bd391e2556be288bdb887304bf26da8ee99a547cb65a8cce841ecb74d',CAST('{"_ghi_chu":"Thang chấm 5 tiêu chí (0–100), dựng trên cách chấm cũ: điểm màu OKLCH góp vào ''dac_trung'', mỗi luật trong rules.json thuộc một tiêu chí (trường criterion) và cộng/trừ điểm tiêu chí đó theo mức. Đổi trọng số ở đây, tổng phải bằng 100. Xem ai-service/app/engine/scoring.py.","criteria":[{"id":"cau_truc","name":"Đúng bộ","en":"Structure/Form","weight":20,"base":80},{"id":"dac_trung","name":"Đặc trưng áo","en":"Garment Characteristics","weight":25,"base":75,"colorShare":0.6},{"id":"phu_kien","name":"Phụ kiện","en":"Accessories","weight":15,"base":75,"baseNone":70},{"id":"boi_canh","name":"Bối cảnh","en":"Context","weight":30,"base":75,"paletteBonus":10},{"id":"cach_tan","name":"Cách tân hợp gu","en":"Modern Remix","weight":10}],"levelPoints":{"ok":10,"consider":-15,"risk":-40},"riskCap":50,"remix":{"modernAccessories":["sneaker","giay_bup_be"],"modernPatterns":["ke_soc","cham_bi"],"byStyle":{"truyen_thong":{"base":85,"perModern":-15},"duong_pho":{"base":70,"perModern":12,"softConsider":true},"toi_gian":{"base":70,"perModern":12,"softConsider":true},"_khac":{"base":75,"perModern":5}}},"rankBonus":{"style":15,"preferredColor":10,"preferredGarment":20},"bands":[{"min":80,"id":"chuan_bo","text":"Chuẩn bộ"},{"min":60,"id":"hop_dip","text":"Hợp dịp"},{"min":0,"id":"can_chinh","text":"Cần chỉnh"}]}' AS JSONB));
