INSERT INTO ai_catalog_entries (dataset_key,entry_key,metadata) VALUES ('culture-cards','CC_AO_DAI',CAST('{"id":"CC_AO_DAI","garmentId":"ao_dai","title":"Áo dài","body":"Áo dài hiện đại phát triển từ áo ngũ thân và được cách tân trong thế kỷ 20 với dáng ôm, xẻ tà cao hai bên. Ngày nay áo dài xuất hiện trong lễ Tết, cưới hỏi, trường học và các sự kiện trang trọng.","sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_catalog_entries (dataset_key,entry_key,metadata) VALUES ('culture-cards','CC_NGU_THAN',CAST('{"id":"CC_NGU_THAN","garmentId":"ao_ngu_than","title":"Áo ngũ thân","body":"Áo ngũ thân may từ năm thân vải: bốn thân chính tượng trưng cho tứ thân phụ mẫu và một thân con phía trong. Áo có cổ đứng, cài khuy chéo sang một bên, phổ biến dưới thời Nguyễn và đang được nhiều bạn trẻ phục dựng.","sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_catalog_entries (dataset_key,entry_key,metadata) VALUES ('culture-cards','CC_TU_THAN',CAST('{"id":"CC_TU_THAN","garmentId":"ao_tu_than","title":"Áo tứ thân","body":"Áo tứ thân gồm bốn vạt, hai vạt trước thường buộc lại, mặc cùng yếm, váy và thắt lưng. Trang phục gắn với hình ảnh người phụ nữ vùng Kinh Bắc và đồng bằng Bắc Bộ.","sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_catalog_entries (dataset_key,entry_key,metadata) VALUES ('culture-cards','CC_NHAT_BINH',CAST('{"id":"CC_NHAT_BINH","garmentId":"nhat_binh","title":"Áo nhật bình","body":"Áo nhật bình là lễ phục của nữ giới trong cung đình triều Nguyễn, nổi bật với phần cổ áo bản rộng phủ qua vai. Vì vốn là lễ phục, áo hợp với lễ hội, sự kiện văn hóa hơn là mặc dạo phố thường ngày.","sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_catalog_entries (dataset_key,entry_key,metadata) VALUES ('culture-cards','CC_BA_BA',CAST('{"id":"CC_BA_BA","garmentId":"ao_ba_ba","title":"Áo bà ba","body":"Áo bà ba là áo ngắn, xẻ hai bên hông, thường mặc cùng quần ống rộng. Trang phục gắn với đời sống thường ngày của người dân Nam Bộ.","sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R01','cau_truc',TRUE,FALSE,CAST('{"id":"R01","level":"ok","criterion":"cau_truc","when":{"all":[{"garment":["ao_tu_than"]},{"hasAccessory":"non_quai_thao"}]},"reason":"Bộ trang phục gắn với vùng Kinh Bắc","suggestion":{"text":"Đội thêm khăn mỏ quạ bên dưới nón, đeo kiềng bạc để trọn bộ quan họ"},"sources":["SRC01"],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R07','cach_tan',TRUE,FALSE,CAST('{"id":"R07","level":"consider","criterion":"cach_tan","when":{"all":[{"garment":["ao_ngu_than"]},{"hasAccessory":"sneaker"}]},"reason":"Cách tân chấp nhận được, nên giữ cổ đứng và 5 khuy","suggestion":{"text":"Chọn sneaker trắng trơn, giữ cổ đứng và đủ 5 khuy"},"sources":["SRC02"],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R12','boi_canh',TRUE,FALSE,CAST('{"id":"R12","level":"risk","criterion":"boi_canh","when":{"all":[{"occasion":["dam_cuoi","tet"]},{"allColorsIn":["trang_nga","trang_tinh"]},{"hasAccessory":"khan_van"}]},"reason":"Toàn màu trắng kèm khăn trắng gợi liên tưởng tang phục","suggestion":{"text":"Đổi màu chính sang đỏ son hoặc hồng đào","patch":{"colors":{"main":"do_son","bottom":"trang_nga"}}},"sources":["SRC03"],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R15','boi_canh',TRUE,FALSE,CAST('{"id":"R15","level":"consider","criterion":"boi_canh","when":{"all":[{"garment":["nhat_binh"]},{"occasion":["dao_pho"]}]},"reason":"Vốn là lễ phục cung đình triều Nguyễn","suggestion":{"text":"Dạo phố nên chọn áo dài hoặc áo ngũ thân"},"sources":["SRC04"],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R20','boi_canh',TRUE,FALSE,CAST('{"id":"R20","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["mua"]},{"hasAccessory":"guoc"}]},"reason":"Trời mưa, guốc gỗ dễ trơn trượt và thấm nước","suggestion":{"text":"Đi giày kín mũi hoặc dép có đế bám thay cho guốc gỗ"},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R21','boi_canh',TRUE,FALSE,CAST('{"id":"R21","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["nang_nong"]},{"setting":["ngoai_troi","ca_hai"]},{"garment":["nhat_binh","ao_tu_than","ao_ngu_than"]}]},"reason":"Áo nhiều lớp, mặc lâu ngoài trời nắng nóng dễ bí và ra mồ hôi","suggestion":{"text":"Chọn áo dài hoặc áo bà ba vải mỏng, hoặc hẹn chụp lúc sáng sớm, chiều muộn"},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R22','boi_canh',TRUE,FALSE,CAST('{"id":"R22","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["nang_nong"]},{"setting":["ngoai_troi","ca_hai"]},{"mainColorIn":["den_tuyen","xanh_lam","nau_dat","tim_hue"]}]},"reason":"Màu tối hấp nắng, mặc ngoài trời lúc nắng nóng sẽ nóng hơn","suggestion":{"text":"Đổi màu chính sang màu sáng như trắng ngà hoặc be kem","patch":{"colors":{"main":"be_kem"}}},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R23','boi_canh',TRUE,FALSE,CAST('{"id":"R23","level":"ok","criterion":"boi_canh","when":{"all":[{"weather":["lanh"]},{"garment":["ao_ngu_than","nhat_binh","ao_tu_than"]}]},"reason":"Áo nhiều lớp, may dày, hợp với tiết trời se lạnh","suggestion":{"text":"Có thể mặc thêm áo lót giữ nhiệt bên trong"},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R24','boi_canh',TRUE,FALSE,CAST('{"id":"R24","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["mua"]},{"mainColorIn":["trang_nga","trang_tinh"]}]},"reason":"Áo màu trắng gặp mưa dễ ướt, lộ và bám bẩn","suggestion":{"text":"Chọn màu đậm hơn như hồng đào hoặc xanh lam","patch":{"colors":{"main":"hong_dao"}}},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R25','boi_canh',TRUE,FALSE,CAST('{"id":"R25","level":"consider","criterion":"boi_canh","when":{"all":[{"role":["khach"]},{"occasion":["dam_cuoi"]},{"garment":["nhat_binh"]}]},"reason":"Nhật bình là lễ phục rất trang trọng, khách dự cưới mặc dễ nổi bật hơn cô dâu","suggestion":{"text":"Khách nên chọn áo dài hoặc áo ngũ thân"},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R26','boi_canh',TRUE,FALSE,CAST('{"id":"R26","level":"consider","criterion":"boi_canh","when":{"all":[{"role":["khach"]},{"occasion":["dam_cuoi"]},{"mainColorIn":["do_son"]}]},"reason":"Màu đỏ thường dành cho cô dâu, khách mặc đỏ dễ trùng với nhân vật chính","suggestion":{"text":"Đổi sang hồng đào hoặc xanh lam","patch":{"colors":{"main":"hong_dao"}}},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R27','boi_canh',TRUE,FALSE,CAST('{"id":"R27","level":"ok","criterion":"boi_canh","when":{"all":[{"role":["nhan_vat_chinh"]},{"occasion":["dam_cuoi"]},{"mainColorIn":["do_son","vang_hoang"]}]},"reason":"Đỏ và vàng là sắc màu quen thuộc của lễ cưới truyền thống","suggestion":{"text":"Có thể thêm khăn vấn cùng tông để trọn bộ"},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R28','cach_tan',TRUE,FALSE,CAST('{"id":"R28","level":"consider","criterion":"cach_tan","when":{"all":[{"occasion":["dam_cuoi","le_hoi_chua"]},{"pattern":["cham_bi","ke_soc"]},{"style":["truyen_thong"]}]},"reason":"Hoạ tiết chấm bi, kẻ sọc mang nét hiện đại, khác tinh thần truyền thống bạn chọn","suggestion":{"text":"Đổi sang vải trơn hoặc hoa văn tròn","patch":{"pattern":"hoa_van_tron"}},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R30','cau_truc',TRUE,FALSE,CAST('{"id":"R30","level":"ok","criterion":"cau_truc","when":{"all":[{"gender":["nam"]},{"garment":["ao_ngu_than","ao_dai"]},{"hasAccessory":"khan_xep"}]},"reason":"Khăn xếp đi cùng áo dài, áo ngũ thân là bộ lễ phục quen thuộc của nam giới","suggestion":{"text":"Chọn khăn cùng tông màu sẫm (đen, xanh lam) để tổng thể trang nhã"},"sources":["SRC05"],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R31','phu_kien',TRUE,FALSE,CAST('{"id":"R31","level":"consider","criterion":"phu_kien","when":{"all":[{"garment":["nhat_binh"]},{"any":[{"hasAccessory":"sneaker"},{"hasAccessory":"giay_bup_be"}]}]},"reason":"Nhật bình là lễ phục, giày hiện đại làm giảm vẻ trang trọng","suggestion":{"text":"Đổi sang hài thêu hoặc guốc gỗ"},"sources":["SRC04"],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R32','phu_kien',TRUE,FALSE,CAST('{"id":"R32","level":"ok","criterion":"phu_kien","when":{"all":[{"hasAccessory":"hai_theu"},{"any":[{"garment":["nhat_binh","ao_ngu_than"]},{"occasion":["dam_cuoi"]}]}]},"reason":"Hài thêu hợp với lễ phục và không khí lễ cưới","suggestion":{"text":"Chọn màu hài trùng màu điểm nhấn của khăn để đồng bộ"},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R33','phu_kien',TRUE,FALSE,CAST('{"id":"R33","level":"consider","criterion":"phu_kien","when":{"all":[{"hasAccessory":"non_quai_thao"},{"garment":["ao_dai","ao_ba_ba"]}]},"reason":"Nón quai thao gắn với áo tứ thân của liền chị quan họ, đi với áo dài hay bà ba dễ lệch tinh thần","suggestion":{"text":"Đổi sang nón lá, hoặc đổi áo sang áo tứ thân"},"sources":["SRC01"],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R34','phu_kien',TRUE,FALSE,CAST('{"id":"R34","level":"ok","criterion":"phu_kien","when":{"all":[{"garment":["ao_tu_than"]},{"any":[{"hasAccessory":"khan_mo_qua"},{"hasAccessory":"kieng_bac"}]}]},"reason":"Khăn mỏ quạ, kiềng bạc là phụ kiện quen thuộc đi cùng áo tứ thân","suggestion":{"text":"Đi lễ hội có thể thêm nón quai thao; chụp ảnh trong nhà thì khăn mỏ quạ là đủ"},"sources":["SRC01"],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R35','boi_canh',TRUE,FALSE,CAST('{"id":"R35","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["mua"]},{"hasAccessory":"quat_giay"}]},"reason":"Quạt giấy gặp mưa dễ ướt, rách","suggestion":{"text":"Thay bằng túi cói hoặc để quạt cho buổi chụp trong nhà"},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R36','boi_canh',TRUE,FALSE,CAST('{"id":"R36","level":"consider","criterion":"boi_canh","when":{"all":[{"role":["khach"]},{"occasion":["dam_cuoi"]},{"pattern":["phuong_hoang"]}]},"reason":"Phượng hoàng thường là hoạ tiết áo cưới của cô dâu, khách mặc dễ trùng nhân vật chính","suggestion":{"text":"Khách dự cưới nên chọn cành đào, sen hoặc hạc và mai","patch":{"pattern":"canh_dao"}},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R37','dac_trung',TRUE,FALSE,CAST('{"id":"R37","level":"ok","criterion":"dac_trung","when":{"all":[{"pattern":["sen","hoi_van","hac_mai"]},{"occasion":["le_hoi_chua","tet"]}]},"reason":"Sen, hồi văn, hạc và mai là hoạ tiết truyền thống, hợp không khí lễ hội, ngày Tết","suggestion":{"text":"Giữ nền trơn một màu để hoạ tiết nổi bật"},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R38','dac_trung',TRUE,FALSE,CAST('{"id":"R38","level":"ok","criterion":"dac_trung","when":{"all":[{"gender":["nam"]},{"pattern":["tung","truc","rong_may","song_nuoc"]}]},"reason":"Tùng, trúc, rồng, sóng nước là hoạ tiết quen thuộc trên áo nam, gợi khí chất vững vàng","suggestion":{"text":"Chọn nền xanh lam hoặc nâu đất để hoạ tiết vàng nổi bật"},"sources":[],"verified":false}' AS JSONB));
INSERT INTO ai_cultural_rules (rule_key,criterion,active,verified,metadata) VALUES ('R39','dac_trung',TRUE,FALSE,CAST('{"id":"R39","level":"ok","criterion":"dac_trung","when":{"all":[{"pattern":["mai_vang","canh_dao"]},{"occasion":["tet"]}]},"reason":"Mai vàng, hoa đào là hoa ngày Tết, hợp không khí du xuân","suggestion":{"text":"Kết hợp khăn vấn hoặc khăn xếp cùng tông với hoa"},"sources":[],"verified":false}' AS JSONB));
