INSERT INTO quiz_questions (question_key,sort_order,metadata) VALUES ('role',4,CAST('{"id":"role","field":"role","type":"single","required":false,"question":"Bạn tham gia với vai trò gì?","options":[{"value":"khach","label":"Khách mời"},{"value":"nhan_vat_chinh","label":"Nhân vật chính (cô dâu, chú rể, người tốt nghiệp…)"},{"value":"be_trap","label":"Bê tráp / phụ dâu, phụ rể"},{"value":"nhom","label":"Đi cùng nhóm / cả lớp"},{"value":"chup_anh","label":"Đi chơi, chụp ảnh"}],"placeholder":"Ví dụ: mình là phù dâu"}' AS JSONB));
